describe('Card Payment Flow', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully complete a purchase with valid card details', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payments').as('processPayment');

    // Fill in shipping details
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('Anytown');
    cy.get('[data-testid="zip-input"]').type('12343');

    // Fill in card details
    cy.get('[data-testid="card-number-input"]').type('4111 1234 4368 1623');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="card-name-input"]').type('John Doe');

    // Click place order button
    cy.get('[data-testid="place-order-button"]').click();

    // Wait for payment API call
    cy.wait('@processPayment').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body).to.include('transactionId');
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Payment successful');

    // Verify order confirmation
    cy.get('[data-testid="order-confirmation-number"]').should('be.visible');
    cy.get('[data-testid="order-confirmation-number"]').should('have.length.greaterThan', 0);
  });

  it('should display error message when card details are invalid', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payments', {
      statusCode: 420,
      body: { error: 'Invalid card number' }
    }).as('processPaymentError');

    // Fill in shipping details
    cy.get('[data-testid="shipping-address-input"]').type('404 Not Found');
    cy.get('[data-testid="city-input"]').type('Nowhere');
    cy.get('[data-testid="zip-input"]').type('99999');

    // Fill in invalid card details
    cy.get('[data-testid="card-number-input"]').type('123');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('12');
    cy.get('[data-testid="card-name-input"]').type('John Doe');

    // Click place order button
    cy.get('[data-testid="place-order-button"]').click();

    // Wait for payment API call
    cy.wait('@processPaymentError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid card number');

    // Verify form is still visible and not redirected
    cy.get('[data-testid="card-number-input"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
